"use client"

import { SearchIcon, XIcon } from "lucide-react"

import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"

import { useDebouncedInput } from "@/components/openlmis/search-input/use-debounced-input"

type SearchInputProps = {
  value: string
  /** Called once typing pauses, on Enter, on blur, and at once when cleared. */
  onValueChange: (value: string) => void
  placeholder?: string
  /** Accessible name, when the placeholder alone does not say what is searched. */
  label?: string
  clearLabel?: string
  /** Milliseconds of quiet before a value is reported. */
  delay?: number
}

export function SearchInput({
  value,
  onValueChange,
  placeholder = "Search...",
  label,
  clearLabel = "Clear Search",
  delay,
}: SearchInputProps) {
  const { draft, commit, inputProps } = useDebouncedInput(
    value,
    onValueChange,
    delay
  )

  return (
    <InputGroup>
      <InputGroupAddon>
        <SearchIcon />
      </InputGroupAddon>
      <InputGroupInput
        aria-label={label ?? placeholder}
        placeholder={placeholder}
        type="text"
        {...inputProps}
      />
      {draft && (
        <InputGroupAddon align="inline-end">
          <InputGroupButton
            aria-label={clearLabel}
            onClick={() => commit("")}
            size="icon-xs"
          >
            <XIcon />
          </InputGroupButton>
        </InputGroupAddon>
      )}
    </InputGroup>
  )
}

"use client"

import {
  type ChangeEvent,
  type KeyboardEvent,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react"

/** Draft for a text input that reports after a pause and otherwise follows the upstream value. */
export function useDebouncedInput(
  value: string,
  onValueChange: (value: string) => void,
  delay = 300
) {
  const [draft, setDraft] = useState(value)
  const [syncedValue, setSyncedValue] = useState(value)
  const [isTyping, setIsTyping] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined)
  const latestOnValueChange = useRef(onValueChange)

  useLayoutEffect(() => {
    latestOnValueChange.current = onValueChange
  })

  // Upstream wins unless the user is mid-typing; an echo that only trims the draft keeps it.
  if (value !== syncedValue) {
    setSyncedValue(value)
    if (!isTyping && value !== draft.trim()) setDraft(value)
  }

  // Leaving the page drops unsent typing; sending it would update a page already gone.
  useEffect(() => () => clearTimeout(timer.current), [])

  const emit = (next: string) => {
    clearTimeout(timer.current)
    setIsTyping(false)
    latestOnValueChange.current(next)
  }

  const change = (next: string) => {
    setDraft(next)
    setIsTyping(true)
    clearTimeout(timer.current)
    timer.current = setTimeout(() => emit(next), delay)
  }

  const commit = (next: string) => {
    setDraft(next)
    emit(next)
  }

  // Leaving the field, e.g. to press Clear Filters, sends what was typed first so nothing arrives after it.
  const flush = () => {
    if (isTyping) emit(draft)
  }

  const inputProps = {
    value: draft,
    onChange: (event: ChangeEvent<HTMLInputElement>) =>
      change(event.target.value),
    onBlur: flush,
    onKeyDown: (event: KeyboardEvent<HTMLInputElement>) => {
      if (event.key === "Enter") commit(event.currentTarget.value)
    },
  }

  return { draft, commit, inputProps }
}
